using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using Autodesk.AutoCAD.ApplicationServices;using Autodesk.AutoCAD.EditorInput;using App=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class PaperGroundcoverTestsV1 {
 public class Config{public string input,input_sha256,template_handle,output,receipt;}
 static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=100000000};
 static void Need(bool ok,string m){if(!ok)throw new InvalidOperationException(m);}
 static object Get(Entity e,string n){var c=e.AcadObject;return c.GetType().InvokeMember(n,BindingFlags.GetProperty,null,c,null);}
 static string Shape(Database d,string[] h){return (string)typeof(NativeGroundcoverCreateV1).GetMethod("Shape",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{d,h});}
 [CommandMethod("HLCADPAPERLEADERTESTV7",CommandFlags.Session)]public void Test(){
  var original=App.DocumentManager.MdiActiveDocument;var old=HostApplicationServices.WorkingDatabase;var a=original.Editor.GetString(new PromptStringOptions("\nPaper native test config: "){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;Config c=null;Document staging=null;
  try{c=J.Deserialize<Config>(File.ReadAllText(a.StringResult.Trim('"')));Need(NativeGeometryReadV1.Hash(c.input)==c.input_sha256&&!File.Exists(c.output)&&!File.Exists(c.receipt),"TEST_INPUT_OUTPUT_IDENTITY");string tmp=c.output+".staging.dwg";File.Copy(c.input,tmp,false);staging=App.DocumentManager.Open(tmp,false);App.DocumentManager.MdiActiveDocument=staging;HostApplicationServices.WorkingDatabase=staging.Database;
   string target,layout,beforeSource,after;int rejected=0;object baseline_followers=null;NativeGroundcoverCreateV1.Item item;
   using(staging.LockDocument()){
    var db=staging.Database;beforeSource=Shape(db,new[]{c.template_handle});
    using(var tr=db.TransactionManager.StartTransaction()){
     var ld=(DBDictionary)tr.GetObject(db.LayoutDictionaryId,OpenMode.ForRead);Layout paper=null;foreach(DBDictionaryEntry row in ld){var found=(Layout)tr.GetObject(row.Value,OpenMode.ForRead);if(!found.ModelType){paper=found;break;}}Need(paper!=null,"PAPER_FIXTURE_LAYOUT_MISSING");layout=paper.LayoutName;
     var source=db.GetObjectId(false,new Handle(Convert.ToInt64(c.template_handle,16)),0);var map=new IdMapping();db.DeepCloneObjects(new ObjectIdCollection(new[]{source}),paper.BlockTableRecordId,map,false);var e=(Entity)tr.GetObject(map[source].Value,OpenMode.ForRead);target=e.Handle.ToString();
     var g=new GripDataCollection();e.GetGripPoints(g,1,5,Vector3d.ZAxis,GetGripPointsFlags.GripPointsOnly);Need(g.Count==4,"FIXTURE_FOUR_GRIPS_REQUIRED");var p=g[0].GripPoint;
     item=new NativeGroundcoverCreateV1.Item{template_handle=target,layer=e.Layer,layout=layout,expected=new NativeGroundcoverCreateV1.Expected{up=(string)Get(e,"UpText"),down=(string)Get(e,"DownText"),height=(string)Get(e,"Height"),scale=Convert.ToDouble(Get(e,"Scale")),rotation=Convert.ToDouble(Get(e,"LayoutRotation")),grips=g.Cast<GripData>().Select(x=>new[]{x.GripPoint.X,x.GripPoint.Y,x.GripPoint.Z}).ToArray()},grips=g.Cast<GripData>().Take(3).Select(x=>new[]{x.GripPoint.X+20,x.GripPoint.Y+10,x.GripPoint.Z}).ToArray()};
     var owner=(BlockTableRecord)tr.GetObject(paper.BlockTableRecordId,OpenMode.ForWrite);var line=new Line(new Point3d(-1,-2,0),new Point3d(-3,-4,0));owner.AppendEntity(line);tr.AddNewlyCreatedDBObject(line,true);tr.Commit();
    }
    string initial=Shape(db,new[]{target});
    foreach(string wrong in new[]{"Model","__ABSENT_PAPER_LAYOUT__"}){item.layout=wrong;bool failed=false;try{NativeGroundcoverCreateV1.Apply(staging,new NativeGroundcoverCreateV1.Job{update_existing=true,items=new[]{item}},()=>{});}catch(InvalidOperationException){failed=true;}Need(failed&&CadValueCompareV1.Json(initial,Shape(db,new[]{target})),"OWNER_REJECTION_OR_ROLLBACK_FAILED");rejected++;}
    using(var tr=db.TransactionManager.StartTransaction()){var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(target,16)),0),OpenMode.ForWrite);var g=new GripDataCollection();e.GetGripPoints(g,1,5,Vector3d.ZAxis,GetGripPointsFlags.GripPointsOnly);var oldPoints=g.Cast<GripData>().Select(x=>x.GripPoint).ToArray();var one=new GripDataCollection();one.Add(g[0]);e.MoveGripPointsAt(one,new Vector3d(5,2,0),(MoveGripPointsFlags)0);g=new GripDataCollection();e.GetGripPoints(g,1,5,Vector3d.ZAxis,GetGripPointsFlags.GripPointsOnly);var now=g.Cast<GripData>().Select(x=>x.GripPoint).ToArray();baseline_followers=new{control_index=0,deltas=now.Select((x,k)=>new[]{x.X-oldPoints[k].X,x.Y-oldPoints[k].Y,x.Z-oldPoints[k].Z}).ToArray()};item.expected.grips=now.Select(x=>new[]{x.X,x.Y,x.Z}).ToArray();tr.Commit();}
    item.layout=layout;NativeGroundcoverCreateV1.Apply(staging,new NativeGroundcoverCreateV1.Job{update_existing=true,items=new[]{item}},()=>{});
    using(var tr=db.TransactionManager.StartTransaction()){var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(target,16)),0),OpenMode.ForRead);var g=new GripDataCollection();e.GetGripPoints(g,1,5,Vector3d.ZAxis,GetGripPointsFlags.GripPointsOnly);item.expected.grips=g.Cast<GripData>().Select(x=>new[]{x.GripPoint.X,x.GripPoint.Y,x.GripPoint.Z}).ToArray();var origin=g[0].GripPoint;var end=origin+(g[1].GripPoint-origin)*.8;var anchor=origin+(g[2].GripPoint-origin)*.5;item.grips=new[]{new[]{origin.X,origin.Y,origin.Z},new[]{end.X,end.Y,end.Z},new[]{anchor.X,anchor.Y,anchor.Z}};}NativeGroundcoverCreateV1.Apply(staging,new NativeGroundcoverCreateV1.Job{update_existing=true,items=new[]{item}},()=>{});
    using(var tr=db.TransactionManager.StartTransaction()){var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(target,16)),0),OpenMode.ForRead);var g=new GripDataCollection();e.GetGripPoints(g,1,5,Vector3d.ZAxis,GetGripPointsFlags.GripPointsOnly);item.expected.grips=g.Cast<GripData>().Select(x=>new[]{x.GripPoint.X,x.GripPoint.Y,x.GripPoint.Z}).ToArray();item.grips=null;double angle=Convert.ToDouble(Get(e,"LayoutRotation"))*Math.PI/180;item.text_grip=new[]{g[3].GripPoint.X+3*Math.Cos(angle),g[3].GripPoint.Y+3*Math.Sin(angle),g[3].GripPoint.Z};}string preRejected=Shape(db,new[]{target});bool refused=false;try{NativeGroundcoverCreateV1.Apply(staging,new NativeGroundcoverCreateV1.Job{update_existing=true,items=new[]{item}},()=>{});}catch(InvalidOperationException){refused=true;}Need(refused&&CadValueCompareV1.Json(preRejected,Shape(db,new[]{target})),"TEXT_CONTROL_MUST_REJECT_WITHOUT_CHANGE");
    Need(CadValueCompareV1.Json(beforeSource,Shape(db,new[]{c.template_handle})),"MODEL_TEMPLATE_CHANGED");after=Shape(db,new[]{target});staging.Database.SaveAs(c.output,DwgVersion.AC1032);
   }
   App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=old;staging.CloseAndDiscard();staging=null;
   staging=App.DocumentManager.Open(c.output,true);App.DocumentManager.MdiActiveDocument=staging;HostApplicationServices.WorkingDatabase=staging.Database;
   using(staging.LockDocument()){Need(CadValueCompareV1.Json(after,Shape(staging.Database,new[]{target})),"PAPER_LEADER_REOPEN_CHANGED");Need(CadValueCompareV1.Json(beforeSource,Shape(staging.Database,new[]{c.template_handle})),"SOURCE_REOPEN_CHANGED");}
   File.WriteAllText(c.receipt,J.Serialize(new{status="ISOLATED_PAPER_LEADER_SAVE_REOPEN_VERIFIED",layout,target,baseline_followers,owner_rejection_cases=rejected,native_topology_guard=true,unselected_write_guard=true,same_orientation_orthogonal_shortening=true,text_grip_rejected_without_change=true,source_unchanged=NativeGeometryReadV1.Hash(c.input)==c.input_sha256,output=c.output,sha256=NativeGeometryReadV1.Hash(c.output),entities=J.DeserializeObject(after)}));
  }catch(System.Exception e){if(c!=null&&!File.Exists(c.receipt))File.WriteAllText(c.receipt,J.Serialize(new{status="FAIL",error=e.ToString()}));}
  finally{App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=old;if(staging!=null)staging.CloseAndDiscard();}
 }

 [CommandMethod("HLCADLEADERCONTROLTESTV1",CommandFlags.Session)] public void ControlTest(){
 var original=App.DocumentManager.MdiActiveDocument;var old=HostApplicationServices.WorkingDatabase;var a=original.Editor.GetString(new PromptStringOptions("\nControl test config: "){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;Config c=null;Document d=null;
 try{c=J.Deserialize<Config>(File.ReadAllText(a.StringResult.Trim('"')));Need(NativeGeometryReadV1.Hash(c.input)==c.input_sha256&&!File.Exists(c.output)&&!File.Exists(c.receipt),"TEST_IDENTITY");File.Copy(c.input,c.output+".staging.dwg",false);d=App.DocumentManager.Open(c.output+".staging.dwg",false);App.DocumentManager.MdiActiveDocument=d;HostApplicationServices.WorkingDatabase=d.Database;var records=new System.Collections.Generic.List<object>();var handles=new System.Collections.Generic.List<string>();string initial,after;
 using(d.LockDocument()){var db=d.Database;initial=Shape(db,new[]{c.template_handle});
 for(int k=0;k<4;k++){string h;using(var tr=db.TransactionManager.StartTransaction()){var source=db.GetObjectId(false,new Handle(Convert.ToInt64(c.template_handle,16)),0);var e=(Entity)tr.GetObject(source,OpenMode.ForRead);var map=new IdMapping();db.DeepCloneObjects(new ObjectIdCollection(new[]{source}),e.OwnerId,map,false);h=map[source].Value.Handle.ToString();tr.Commit();}string before=Shape(db,new[]{h});using(var tr=db.TransactionManager.StartTransaction()){var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(h,16)),0),OpenMode.ForWrite);var g=new GripDataCollection();e.GetGripPoints(g,1,5,Vector3d.ZAxis,GetGripPointsFlags.GripPointsOnly);Need(g.Count==4,"FOUR_GRIPS_REQUIRED");var one=new GripDataCollection();one.Add(g[k]);e.MoveGripPointsAt(one,new Vector3d(3,0,0),(MoveGripPointsFlags)0);tr.Commit();}records.Add(new{index=k,before=J.DeserializeObject(before),after=J.DeserializeObject(Shape(db,new[]{h}))});handles.Add(h);}
 Need(CadValueCompareV1.Json(initial,Shape(db,new[]{c.template_handle})),"ORIGINAL_CHANGED");after=Shape(db,handles.ToArray());db.SaveAs(c.output,DwgVersion.AC1032);}
 App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=old;d.CloseAndDiscard();d=null;d=App.DocumentManager.Open(c.output,true);App.DocumentManager.MdiActiveDocument=d;HostApplicationServices.WorkingDatabase=d.Database;using(d.LockDocument()){Need(CadValueCompareV1.Json(after,Shape(d.Database,handles.ToArray())),"REOPEN_CHANGED");}
 File.WriteAllText(c.receipt,J.Serialize(new{status="CONTROL_LINKAGE_OBSERVED_SAVED_REOPENED",source_unchanged=NativeGeometryReadV1.Hash(c.input)==c.input_sha256,records,output=c.output,sha256=NativeGeometryReadV1.Hash(c.output)}));
 }catch(System.Exception ex){if(c!=null&&!File.Exists(c.receipt))File.WriteAllText(c.receipt,J.Serialize(new{status="FAIL",error=ex.ToString()}));}finally{App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=old;if(d!=null)d.CloseAndDiscard();}
 }
